details.golden_sql:
SELECT COUNT(*) AS teacher_cnt
FROM edu_dw.ads_teacher_workload
WHERE term_id = 202601 AND workload_level = '重';

SELECT ROUND(avg_score, 2) AS avg_score, fail_cnt
FROM edu_dw.dws_student_term
WHERE term_id = 202601 AND student_no = 'S013172';

SELECT term_name, ROUND(avg_score, 2) AS avg_score
FROM edu_dw.ads_term_trend
ORDER BY seq_no ASC;

SELECT term_name, ROUND(attend_rate, 4) AS attend_rate
FROM edu_dw.ads_term_trend
ORDER BY seq_no ASC;

SELECT ROUND(avg_score, 2) AS avg_score
FROM edu_dw.ads_term_kpi
WHERE term_id = 202601;

SELECT ROUND(avg_first, 2) AS avg_first
FROM edu_dw.dws_student_term
WHERE term_id = 202601 AND student_no = 'S013172';

SELECT ROUND(1 - fail_rate, 4) AS pass_rate
FROM edu_dw.ads_term_kpi
WHERE term_id = 202601;
